package com.aiuml.architect.diagram;
import com.aiuml.architect.project.ProjectService; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional class DiagramService { private final DiagramRepository diagrams; private final DiagramVersionRepository versions; private final ObjectMapper mapper; private final ProjectService projects; DiagramService(DiagramRepository d,DiagramVersionRepository v,ObjectMapper m,ProjectService p){diagrams=d;versions=v;mapper=m;projects=p;} DiagramDocument create(UUID projectId,UUID userId,DiagramDocument raw){projects.requireMember(projectId,userId);UUID id=UUID.randomUUID();return save(id,projectId,userId,raw,true);} DiagramDocument get(UUID projectId,UUID id,UUID userId){projects.requireMember(projectId,userId);return toDocument(find(projectId,id));} List<DiagramSummary> list(UUID projectId,UUID userId){projects.requireMember(projectId,userId);return diagrams.findByProjectIdOrderByUpdatedAtDesc(projectId).stream().map(e->new DiagramSummary(e.id,e.name,e.updatedAt)).toList();} DiagramDocument update(UUID projectId,UUID id,UUID userId,DiagramDocument raw){projects.requireMember(projectId,userId);return save(id,projectId,userId,raw,false);} List<DiagramVersionResponse> versions(UUID projectId,UUID id,UUID userId){get(projectId,id,userId);return versions.findByDiagramIdOrderByVersionNumberDesc(id).stream().map(v->new DiagramVersionResponse(v.id,v.versionNumber,v.createdAt,mapper.convertValue(v.document,DiagramDocument.class))).toList();} DiagramDocument restore(UUID projectId,UUID id,UUID userId,int n){get(projectId,id,userId);var v=versions.findByDiagramIdAndVersionNumber(id,n).orElseThrow(()->new NoSuchElementException("Version not found"));return save(id,projectId,userId,mapper.convertValue(v.document,DiagramDocument.class),false);} private DiagramEntity find(UUID p,UUID id){return diagrams.findByIdAndProjectId(id,p).orElseThrow(()->new NoSuchElementException("Diagram not found"));} private DiagramDocument save(UUID id,UUID projectId,UUID userId,DiagramDocument raw,boolean create){var doc=new DiagramDocument(1,id,raw.name(),raw.classes(),raw.relationships());var json=mapper.valueToTree(doc);DiagramEntity e=create?new DiagramEntity(id,projectId,doc.name(),json,userId):find(projectId,id);e.name=doc.name();e.document=json;diagrams.save(e);int next=versions.findFirstByDiagramIdOrderByVersionNumberDesc(id).map(v->v.versionNumber+1).orElse(1);versions.save(new DiagramVersionEntity(id,next,json,userId));return doc;} private DiagramDocument toDocument(DiagramEntity e){return mapper.convertValue(e.document,DiagramDocument.class);} record DiagramSummary(UUID id,String name,java.time.Instant updatedAt){} record DiagramVersionResponse(UUID id,int versionNumber,java.time.Instant createdAt,DiagramDocument document){} }
